package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="archivos_resultados_estudios") public class ArchivoResultadoEstudio { @Id @GeneratedValue private UUID id; @Column(name="empresa_id") private UUID empresaId; @Column(name="paciente_id") private UUID pacienteId; @Column(name="orden_id") private UUID ordenId; @Column(name="detalle_orden_id") private UUID detalleOrdenId; @Column(name="storage_key") private String storageKey; @Column(name="nombre_original") private String nombreOriginal; @Column(name="mime_type") private String mimeType; @Column(name="tamanio_bytes") private long tamanioBytes; private String checksum; @Column(name="subido_por") private UUID subidoPor; @Column(name="creado_en") private LocalDateTime creadoEn; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public UUID getDetalleOrdenId(){return detalleOrdenId;} public String getNombreOriginal(){return nombreOriginal;} public String getMimeType(){return mimeType;} public long getTamanioBytes(){return tamanioBytes;} public String getStorageKey(){return storageKey;} public void setEmpresaId(UUID v){empresaId=v;} public void setPacienteId(UUID v){pacienteId=v;} public void setOrdenId(UUID v){ordenId=v;} public void setDetalleOrdenId(UUID v){detalleOrdenId=v;} public void setStorageKey(String v){storageKey=v;} public void setNombreOriginal(String v){nombreOriginal=v;} public void setMimeType(String v){mimeType=v;} public void setTamanioBytes(long v){tamanioBytes=v;} public void setChecksum(String v){checksum=v;} public void setSubidoPor(UUID v){subidoPor=v;} public void setCreadoEn(LocalDateTime v){creadoEn=v;} }
